INSERT OR IGNORE INTO faq_items(id, question, answer, sort_order, published) VALUES
  (1, 'Как оплатить заказ?', 'После оформления заказа бот покажет точную сумму и реквизиты СБП. Оплата подтверждается магазином после проверки поступления.', 1, 1),
  (2, 'Сколько стоит доставка?', 'Стоимость доставки бот рассчитает при оформлении. Самовывоз бесплатный.', 2, 1),
  (3, 'Можно ли заказать пошив по своим размерам?', 'Да, отправьте заявку через кнопку «Сшить на заказ». Магазин свяжется с вами для уточнения ткани, размеров и сроков.', 3, 1),
  (4, 'Как ухаживать за изделием?', 'Рекомендации по уходу указаны в описании каждого товара. Перед стиркой проверяйте ярлык изделия.', 4, 1),
  (5, 'Как узнать статус заказа?', 'Нажмите «Мои заказы» в этом чате. Статусы обновляются после обработки заказа магазином.', 5, 1),
  (6, 'Как связаться с магазином?', 'Напишите в этот чат или позвоните по телефону Family Soft, указанному в разделе «Контакты».', 6, 1);
